    if ability_ready(1) and slot_stun(1) > 0 and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            if fuel_remaining() > 30000:
                dash_towards(1, unit_position(t))
        elif slot_radius(1) > 0:
            cast_at_tile(1, unit_position(t))
        else:
            cast_at_unit(1, t)
    elif ability_ready(0) and slot_stun(0) > 0 and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            if fuel_remaining() > 30000:
                dash_towards(0, unit_position(t))
        elif slot_radius(0) > 0:
            cast_at_tile(0, unit_position(t))
        else:
            cast_at_unit(0, t)
    if i_am_ranged() and can_move() and distance(position(), unit_position(t)) <= 1 and not contains(wallring, position()):
        move_away_from(unit_position(t))
    if can_attack() and (distance(position(), unit_position(t)) <= 1 or (i_am_ranged() and distance(position(), unit_position(t)) <= 3)):
        attack(t)
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)
    if ability_ready(0) and slot_is_aoe(0) and distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
        cast_at_tile(0, unit_position(t))
    elif ability_ready(0) and slot_is_damage(0) and distance(position(), unit_position(t)) <= slot_range(0):
        cast_at_unit(0, t)
    if ability_ready(1) and slot_is_aoe(1) and distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
        cast_at_tile(1, unit_position(t))
    elif ability_ready(1) and slot_is_damage(1) and distance(position(), unit_position(t)) <= slot_range(1):
        cast_at_unit(1, t)
    if ability_ready(0) and slot_is_shield(0):
        cast_self(0)
    if ability_ready(1) and slot_is_shield(1):
        cast_self(1)
    if can_move() and can_attack():
        if distance(position(), unit_position(t)) > 1:
            if not (i_am_ranged() and distance(position(), unit_position(t)) <= 3):
